    93	    @Transactional(readOnly = true)
    94	    public boolean isSlotAvailable(String providerCode, ZonedDateTime start, ZonedDateTime end) {
    95	        var provider = providerRepository.findByProviderCode(providerCode)
    96	                .orElseThrow(() -> new IllegalArgumentException("Unknown provider " + providerCode));
    97	
    98	        ZoneId zone = clinicClock.now().getZone();
    99	
   100	        ZonedDateTime normalizedStart = start.toLocalDateTime().atZone(zone);
   101	        ZonedDateTime normalizedEnd = end.toLocalDateTime().atZone(zone);
   102	
   103	        var conflicts = appointmentRepository.findOverlappingAppointments(provider.getId(), normalizedStart, normalizedEnd);
   104	        return conflicts.isEmpty();
   105	    }
   106	
   107	    @Transactional
   108	    public Appointment bookAppointment(String patientCode,
   109	                                       String providerCode,
   110	                                       String appointmentTypeCode,
   111	                                       ZonedDateTime start,
   112	                                       ZonedDateTime end,
   113	                                       String roomCode) {
   114	
   115	        var patient = patientQueryService.findEntity(patientCode);
   116	        var provider = providerRepository.findByProviderCode(providerCode)
   117	                .orElseThrow(() -> new IllegalArgumentException("Unknown provider " + providerCode));
   118	        AppointmentType appointmentType = appointmentTypeRepository.findByTypeCode(appointmentTypeCode)
   119	                .orElseGet(() -> appointmentTypeRepository.findByTypeCode("CHECKUP")
   120	                        .orElseThrow(() -> new IllegalStateException("Appointment type reference data missing")));
   121	
   122	        Room room = roomCode == null ? null : roomRepository.findByRoomCode(roomCode)
   123	                .orElse(null); // optional room; telehealth visits may not map cleanly
   124	
   125	        ensureNoConflicts(provider, start, end);
   126	
   127	        Timer.Sample sample = Timer.start(meterRegistry);
   128	        try {
   129	            Appointment appointment = new Appointment();
   130	            appointment.setPatient(patient);
   131	            appointment.setProvider(provider);
   132	            appointment.setAppointmentType(appointmentType);
   133	            appointment.setRoom(room);
   134	            appointment.setSlot(new AppointmentSlot(start, end));
   135	            appointment.setStatus(AppointmentStatus.SCHEDULED);
   136	            appointment.setLegacyNotes("Created via API " + UUID.randomUUID());
   137	
   138	            Appointment persisted = appointmentRepository.save(appointment);
   139	            persisted.getPatient().getFirstName();
   140	            persisted.getProvider().getFirstName();
   141	            return persisted;
   142	        } finally {
   143	            sample.stop(meterRegistry.timer("appointments.service.duration"));
   144	        }
   145	    }
   146	
   147	    private void ensureNoConflicts(com.clinictraining.patient.model.Provider provider, ZonedDateTime start, ZonedDateTime end) {
   148	        ZoneId zone = clinicClock.now().getZone();
   149	
   150	        ZonedDateTime normalizedStart = start.toLocalDateTime().atZone(zone);
   151	        ZonedDateTime normalizedEnd = end.toLocalDateTime().atZone(zone);
   152	
   153	        var conflicts = appointmentRepository.findOverlappingAppointments(provider.getId(), normalizedStart, normalizedEnd);
   154	        if (!conflicts.isEmpty()) {
   155	            log.warn("Detected {} conflicting appointments for provider {}", conflicts.size(), provider.getId());
   156	            throw new IllegalStateException("Conflicting appointment detected");
   157	        }
   158	    }
   159	
   160	    private String formatPreview(Appointment appointment) {
   161	        String patientName = safeName(appointment.getPatient().getFirstName(), appointment.getPatient().getLastName());
   162	        String providerName = appointment.getProvider().getLastName();
   163	        String slot = appointment.getSlot() == null ? "unscheduled" : appointment.getSlot().getStart().toString();
   164	        return patientName + " with Dr. " + providerName + " on " + slot;
   165	    }
   166	
   167	    private String safeName(String first, String last) {
   168	        return (first == null ? "Unknown" : first) + " " + (last == null ? "" : last);
   169	    }
   170	
   171	    @Transactional
   172	    public Appointment cancelAppointment(Long appointmentId, String reason) {
   173	        Appointment appointment = appointmentRepository.findById(appointmentId)
   174	                .orElseThrow(() -> new IllegalArgumentException("Appointment not found: " + appointmentId));
   175	
   176	        appointment.setStatus(AppointmentStatus.CANCELLED);
   177	
   178	        if (reason != null) {
   179	            String existingNotes = appointment.getLegacyNotes();
   180	            String updatedNotes = (existingNotes != null ? existingNotes + "\n" : "")
   181	                    + "Cancelled: " + reason + " at " + clinicClock.now();
   182	            appointment.setLegacyNotes(updatedNotes);
   183	        }
   184	
   185	        appointment.setUpdatedAt(clinicClock.now());
   186	        Appointment saved = appointmentRepository.save(appointment);
   187	
   188	        log.info("Appointment {} cancelled", appointmentId);
   189	        meterRegistry.counter("appointments.cancelled.count").increment();
   190	
   191	        return saved;
   192	    }
   193	
   194	    @Transactional
   195	    public Appointment updateStatus(Long appointmentId, AppointmentStatus newStatus, String notes) {
   196	        Appointment appointment = appointmentRepository.findById(appointmentId)
   197	                .orElseThrow(() -> new IllegalArgumentException("Appointment not found: " + appointmentId));
   198	
   199	        AppointmentStatus oldStatus = appointment.getStatus();
   200	
   201	        appointment.setStatus(newStatus);
   202	
   203	        if (notes != null) {
   204	            String existingNotes = appointment.getLegacyNotes();
   205	            String updatedNotes = (existingNotes != null ? existingNotes + "\n" : "")
   206	                    + "Status changed from " + oldStatus + " to " + newStatus + ": " + notes;
   207	            appointment.setLegacyNotes(updatedNotes);
   208	        }
   209	
   210	        appointment.setUpdatedAt(clinicClock.now());
   211	
   212	        if (newStatus == AppointmentStatus.COMPLETED && oldStatus != AppointmentStatus.COMPLETED) {
   213	            log.info("Appointment {} completed", appointmentId);
   214	        }
   215	
   216	        Appointment saved = appointmentRepository.save(appointment);
   217	        meterRegistry.counter("appointments.status_changed.count").increment();
   218	
   219	        return saved;
   220	    }
   221	
   222	    @Transactional
   223	    public Appointment rescheduleAppointment(Long appointmentId, ZonedDateTime newStart,
   224	                                             ZonedDateTime newEnd, String roomCode) {
   225	        Appointment appointment = appointmentRepository.findById(appointmentId)
   226	                .orElseThrow(() -> new IllegalArgumentException("Appointment not found: " + appointmentId));
   227	
   228	        var provider = appointment.getProvider();
   229	
   230	        if (!isSlotAvailable(provider.getProviderCode(), newStart, newEnd)) {
   231	            throw new IllegalStateException("Provider not available for new time slot");
   232	        }
   233	
   234	        ZonedDateTime oldStart = appointment.getSlot().getStart();
   235	        appointment.setSlot(new AppointmentSlot(newStart, newEnd));
   236	
   237	        if (roomCode != null) {
   238	            Room room = roomRepository.findByRoomCode(roomCode)
   239	                    .orElseThrow(() -> new IllegalArgumentException("Room not found: " + roomCode));
   240	            appointment.setRoom(room);
   241	        }
   242	
   243	        String note = "Rescheduled from " + oldStart + " to " + newStart + " at " + clinicClock.now();
   244	        String existingNotes = appointment.getLegacyNotes();
   245	        appointment.setLegacyNotes((existingNotes != null ? existingNotes + "\n" : "") + note);
   246	
   247	        appointment.setUpdatedAt(clinicClock.now());
   248	
   249	        Appointment saved = appointmentRepository.save(appointment);
   250	        meterRegistry.counter("appointments.rescheduled.count").increment();
   251	
   252	        return saved;
   253	    }
   254	}

