1	import { useMutation, useQueryClient } from '@tanstack/react-query';
2	import { graphqlClient } from '../../../shared/api/graphql/client';
3	import { queryKeys } from '../../../shared/api/queryKeys';
4	
5	const CREATE_APPOINTMENT_MUTATION = `
6	  mutation CreateAppointment($request: AppointmentInput!) {
7	    createAppointment(request: $request) {
8	      id
9	      appointmentUid
10	      status
11	      startTime
12	      endTime
13	      roomCode
14	    }
15	  }
16	`;
17	
18	interface AppointmentInput {
19	  patientCode: string;
20	  providerCode: string;
21	  appointmentType?: string;
22	  startTime: string;
23	  endTime: string;
24	  roomCode?: string;
25	}
26	
27	interface CreateAppointmentData {
28	  createAppointment: {
29	    id: string;
30	    appointmentUid: string;
31	    status: string;
32	    startTime?: string;
33	    endTime?: string;
34	    roomCode?: string;
35	  };
36	}
37	
38	export const useBookAppointment = () => {
39	  const queryClient = useQueryClient();
40	
41	  return useMutation({
42	    mutationFn: async (input: AppointmentInput) => {
43	      const data = await graphqlClient.request<CreateAppointmentData>(
44	        CREATE_APPOINTMENT_MUTATION,
45	        { request: input }
46	      );
47	      return data.createAppointment;
48	    },
49	    onSuccess: () => {
50	      queryClient.invalidateQueries({ queryKey: queryKeys.appointments.all });
51	      queryClient.invalidateQueries({ queryKey: queryKeys.dashboard.stats() });
52	    },
53	  });
